#!/usr/bin/env python3
"""Generate AI Impact on Global Job Market Trend Analysis Report"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
from matplotlib.gridspec import GridSpec
import base64
from io import BytesIO
from datetime import datetime
import json
import os

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Ensure output directory exists
os.makedirs('/app/output', exist_ok=True)

# Set style
plt.style.use('seaborn-v0_8-whitegrid')
plt.rcParams['figure.facecolor'] = 'white'
plt.rcParams['axes.facecolor'] = 'white'
plt.rcParams['font.family'] = 'DejaVu Sans'

# Color palette
COLORS = {
    'primary': '#1a365d',
    'secondary': '#2c5282',
    'accent': '#3182ce',
    'high_risk': '#c53030',
    'medium_risk': '#d69e2e',
    'low_risk': '#38a169',
    'text': '#2d3748',
    'text_light': '#718096'
}

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150, facecolor='white')
    buf.seek(0)
    img_base64 = base64.b64encode(buf.getvalue()).decode()
    plt.close(fig)
    return img_base64

def save_chart(fig, filename):
    """Save chart to file and return base64"""
    path = f'/app/output/{filename}'
    fig.savefig(path, bbox_inches='tight', dpi=150, facecolor='white')
    plt.close(fig)
    return fig_to_base64(fig)

# ===== KPI CALCULATIONS =====
print("Calculating KPIs...")

# 1. Average AI Risk Score by year
ai_risk_by_year = df.groupby('year')['ai_risk_score'].mean()

# 2. Median Salary by year
salary_by_year = df.groupby('year')['salary'].median()

# 3. Job Survival Rate by year
survival_by_year = df.groupby('year').apply(lambda x: (x['job_survival_class'] >= 1).sum() / len(x) * 100)

# 4. Average Skill Demand Score by year
skill_demand_by_year = df.groupby('year')['skill_demand_score'].mean()

# 5. Total Job Openings by year
openings_by_year = df.groupby('year')['job_openings'].sum()

# By job title
ai_risk_by_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False)
salary_by_job = df.groupby('job_title')['salary'].median().sort_values(ascending=False)

# By country
ai_risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False)
salary_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False)

# By experience level
ai_risk_by_exp = df.groupby('experience_level')['ai_risk_score'].mean()
salary_by_exp = df.groupby('experience_level')['salary'].median()

# By education level
ai_risk_by_edu = df.groupby('education_level')['ai_risk_score'].mean()
salary_by_edu = df.groupby('education_level')['salary'].median()

# By ai_risk_category
survival_by_risk_cat = df.groupby('ai_risk_category').apply(lambda x: (x['job_survival_class'] >= 1).sum() / len(x) * 100)

# Salary bucket distribution
salary_bucket_dist = df['salary_bucket'].value_counts()

# Job survival class distribution
survival_class_dist = df['job_survival_class'].value_counts().sort_index()

# Top skills by demand
skills_top = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False).head(10)

# Skills by AI risk
skills_risk = df.groupby('primary_skill')['ai_risk_score'].mean()

# ===== CHARTS =====
print("Generating charts...")

# Chart 1: AI Risk Score Trend over time
fig, ax = plt.subplots(figsize=(10, 5))
years = ai_risk_by_year.index
ax.plot(years, ai_risk_by_year.values, color=COLORS['high_risk'], linewidth=2.5, marker='o', markersize=6)
ax.fill_between(years, ai_risk_by_year.values, alpha=0.2, color=COLORS['high_risk'])
ax.axhline(y=df['ai_risk_score'].mean(), color=COLORS['text_light'], linestyle='--', label=f'Overall Mean: {df["ai_risk_score"].mean():.2f}')
ax.set_xlabel('Year', fontsize=11)
ax.set_ylabel('Average AI Risk Score', fontsize=11)
ax.set_title('AI Risk Score Trend (2015-2035)', fontsize=14, fontweight='bold')
ax.legend()
ax.set_ylim(0, 1)
chart1_b64 = save_chart(fig, 'ai_risk_trend.png')

# Chart 2: Median Salary Trend
fig, ax = plt.subplots(figsize=(10, 5))
ax.plot(years, salary_by_year.values, color=COLORS['accent'], linewidth=2.5, marker='s', markersize=6)
ax.fill_between(years, salary_by_year.values, alpha=0.2, color=COLORS['accent'])
ax.set_xlabel('Year', fontsize=11)
ax.set_ylabel('Median Salary (USD)', fontsize=11)
ax.set_title('Median Salary Trend (2015-2035)', fontsize=14, fontweight='bold')
ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'${x:,.0f}'))
chart2_b64 = save_chart(fig, 'salary_trend.png')

# Chart 3: Job Survival Rate by Year
fig, ax = plt.subplots(figsize=(10, 5))
ax.plot(years, survival_by_year.values, color=COLORS['low_risk'], linewidth=2.5, marker='^', markersize=6)
ax.fill_between(years, survival_by_year.values, alpha=0.2, color=COLORS['low_risk'])
ax.set_xlabel('Year', fontsize=11)
ax.set_ylabel('Job Survival Rate (%)', fontsize=11)
ax.set_title('Job Survival Rate Trend (2015-2035)', fontsize=14, fontweight='bold')
ax.set_ylim(0, 100)
chart3_b64 = save_chart(fig, 'survival_trend.png')

# Chart 4: AI Risk by Job Title
fig, ax = plt.subplots(figsize=(10, 5))
colors = [COLORS['high_risk'] if x > 0.5 else COLORS['medium_risk'] if x > 0.3 else COLORS['low_risk'] for x in ai_risk_by_job.values]
bars = ax.barh(ai_risk_by_job.index, ai_risk_by_job.values, color=colors)
ax.axvline(x=0.5, color=COLORS['high_risk'], linestyle='--', alpha=0.7, label='High Risk Threshold')
ax.set_xlabel('Average AI Risk Score', fontsize=11)
ax.set_title('AI Risk by Job Title', fontsize=14, fontweight='bold')
chart4_b64 = save_chart(fig, 'ai_risk_by_job.png')

# Chart 5: AI Risk by Country
fig, ax = plt.subplots(figsize=(10, 5))
colors = [COLORS['high_risk'] if x > 0.5 else COLORS['medium_risk'] if x > 0.3 else COLORS['low_risk'] for x in ai_risk_by_country.values]
ax.barh(ai_risk_by_country.index, ai_risk_by_country.values, color=colors)
ax.axvline(x=0.5, color=COLORS['high_risk'], linestyle='--', alpha=0.7)
ax.set_xlabel('Average AI Risk Score', fontsize=11)
ax.set_title('AI Risk by Country', fontsize=14, fontweight='bold')
chart5_b64 = save_chart(fig, 'ai_risk_by_country.png')

# Chart 6: Salary by Country
fig, ax = plt.subplots(figsize=(10, 5))
salary_country_sorted = salary_by_country.sort_values(ascending=True)
ax.barh(salary_country_sorted.index, salary_country_sorted.values, color=COLORS['accent'])
ax.set_xlabel('Median Salary (USD)', fontsize=11)
ax.set_title('Median Salary by Country', fontsize=14, fontweight='bold')
ax.xaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'${x:,.0f}'))
chart6_b64 = save_chart(fig, 'salary_by_country.png')

# Chart 7: AI Risk by Experience Level
fig, ax = plt.subplots(figsize=(8, 5))
exp_order = ['Entry', 'Mid', 'Senior']
ai_risk_by_exp_ordered = ai_risk_by_exp.reindex(exp_order)
colors = [COLORS['low_risk'] if x < 0.3 else COLORS['medium_risk'] if x < 0.5 else COLORS['high_risk'] for x in ai_risk_by_exp_ordered.values]
bars = ax.bar(exp_order, ai_risk_by_exp_ordered.values, color=colors)
ax.set_ylabel('Average AI Risk Score', fontsize=11)
ax.set_title('AI Risk by Experience Level', fontsize=14, fontweight='bold')
for bar, val in zip(bars, ai_risk_by_exp_ordered.values):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.01, f'{val:.2f}', ha='center', fontsize=10)
chart7_b64 = save_chart(fig, 'ai_risk_by_exp.png')

# Chart 8: Salary by Experience Level
fig, ax = plt.subplots(figsize=(8, 5))
salary_by_exp_ordered = salary_by_exp.reindex(exp_order)
bars = ax.bar(exp_order, salary_by_exp_ordered.values, color=COLORS['accent'])
ax.set_ylabel('Median Salary (USD)', fontsize=11)
ax.set_title('Median Salary by Experience Level', fontsize=14, fontweight='bold')
ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'${x:,.0f}'))
for bar, val in zip(bars, salary_by_exp_ordered.values):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 500, f'${val:,.0f}', ha='center', fontsize=10)
chart8_b64 = save_chart(fig, 'salary_by_exp.png')

# Chart 9: Job Openings Trend
fig, ax = plt.subplots(figsize=(10, 5))
ax.plot(years, openings_by_year.values, color=COLORS['secondary'], linewidth=2.5, marker='d', markersize=6)
ax.fill_between(years, openings_by_year.values, alpha=0.2, color=COLORS['secondary'])
ax.set_xlabel('Year', fontsize=11)
